import { ITeacherModel } from '../person/TeacherModel';
import { ICourseImageModel, ICourseVideoModel } from './CourseVideoModel';

export interface ICourseModel {

  id: number;
  name: string;
  price: number;
  offPrice: number;
  viewCount: number;
  shortDescription: string;
  description: string;
  imageUrl: string;
  videoUrl: string;
  createDate: Date;
  lastUpdateDate: Date;
  categoryIds: number[];
  teacher: ITeacherModel;
  isActive: boolean;
  isEdited: boolean;
  isBuy: boolean;
  isVip: boolean;

  courseImages: ICourseImageModel[];
  courseVideos: ICourseVideoModel[];
}

export class CourseModel implements ICourseModel {

  id: number;
  name: string;
  price: number;
  offPrice: number;
  viewCount: number;
  shortDescription: string;
  description: string;
  imageUrl: string;
  videoUrl: string;
  createDate: Date;
  lastUpdateDate: Date;
  categoryIds: number[];
  teacher: ITeacherModel;
  isActive: boolean;
  isEdited: boolean;
  isBuy: boolean;
  isVip: boolean;

  courseImages: ICourseImageModel[];
  courseVideos: ICourseVideoModel[];

  constructor(
    id: number,
    name: string,
    Price: number,
    OffPrice: number,
    ViewCount: number,
    ShortDescription: string,
    Description: string,
    ImageUrl: string,
    VideoUrl: string,
    CreateDate: Date,
    LastUpdateDate: Date,
    categoryIds: number[],
    isActive: boolean
  ) {

    this.id = id;
    this.name = name;
    this.price = Price;
    this.offPrice = OffPrice;
    this.viewCount = ViewCount;
    this.shortDescription = ShortDescription;
    this.description = Description;
    this.imageUrl = ImageUrl;
    this.videoUrl = VideoUrl;
    this.createDate = CreateDate;
    this.lastUpdateDate = LastUpdateDate;
    this.categoryIds = categoryIds;
    this.isActive = isActive;
  }
}

